"""Test block Toasts (Feedback): Short messages that confirm something just happened, bottom right on the desktop and bottom centre on the phone, gone after a few seconds.

Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/feedback/Toasts.md and its markup
(kit/blocks/feedback/Toasts.html, kit/blocks/feedback/Toasts.2.html; source b0bc6db6321a), with the vocabulary in
functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.

Steps (e2e):
  Then I see the toast {text}
  Then I see no toast
  Then I see {n} toasts
  When I press {name} on the toast
  Then the toaster is in the {state} state
States (from the card): Success, Info, Warning, Error, With an action, Hover or focus, Several, Closing, Invitation
sent. Checked by the state step: Success, Error.
"""
from __future__ import annotations

from functional import Registry
from functional import primitives as p

BLOCK = "Toasts"
ROUTE = ""
STATES = ["Success", "Info", "Warning", "Error", "With an action", "Hover or focus", "Several", "Closing", "Invitation sent"]
DEFAULT_STATE = "Success"
CHECKED_STATES = ["Success", "Error"]
DEMO = ["kit/blocks/feedback/Toasts.2.html"]
SELF_TEST = [
    "Then I see the toast \"Note deleted\"",
    "Then I see 1 toasts",
    "Then the toaster is in the \"Success\" state",
    "When I press \"Undo\" on the toast",
]

steps = Registry(block=BLOCK)


class Toasts:
    """The Toasts block on a page: its controls, found as a person finds them (role and name, label, text)."""

    def __init__(self, page, base_url: str = ""):
        self.page = page
        self.base_url = base_url

    def toaster(self):
        return p.control(self.page, css="#toaster", block=BLOCK)

    def toasts(self):
        return p.control(self.toaster(), css=".toast", block=BLOCK)

    def toasts_all(self):
        """Every match, possibly none (for counting)."""
        return self.toaster().locator(".toast")

    def toast(self, text):
        return p.control(self.toaster(), css=".toast", block=BLOCK).filter(has_text=str(text))

    def action(self, name):
        return p.control(self.toaster(), role="button", name=str(name), block=BLOCK)

    def success(self):
        return p.control(self.toaster(), css=".toast[data-category=\"success\"]", block=BLOCK)

    def error(self):
        return p.control(self.toaster(), css=".toast[data-category=\"error\"]", block=BLOCK)

    def expect_state(self, state: str) -> None:
        """Check one of the card's states: Success, Error."""
        b = self
        if state == "Success":
            p.expect_visible(b.success().first)
        elif state == "Error":
            p.expect_visible(b.error().first)
        else:
            raise AssertionError(f"Toasts has no check for the state {state!r}; checked: " + ", ".join(CHECKED_STATES))


@steps.step("Then I see the toast {text}", level="e2e")
def then_i_see_the_toast_text(world, text):
    b = Toasts(world.page, getattr(world, "base_url", ""))
    p.expect_visible(b.toast(text))


@steps.step("Then I see no toast", level="e2e")
def then_i_see_no_toast(world):
    b = Toasts(world.page, getattr(world, "base_url", ""))
    p.expect_count(b.toasts_all(), 0)


@steps.step("Then I see {n} toasts", level="e2e")
def then_i_see_n_toasts(world, n):
    b = Toasts(world.page, getattr(world, "base_url", ""))
    p.expect_count(b.toasts_all(), int(n))


@steps.step("When I press {name} on the toast", level="e2e")
def when_i_press_name_on_the_toast(world, name):
    b = Toasts(world.page, getattr(world, "base_url", ""))
    p.click(b.action(name))


@steps.step("Then the toaster is in the {state} state", level="e2e")
def then_the_toaster_is_in_the_state_state(world, state):
    b = Toasts(world.page, getattr(world, "base_url", ""))
    b.expect_state(state)
